#!/usr/bin/env python3
import sys


def main():
    count_lines = False
    count_words = False
    count_chars = False
    have_flag = False
    filename = None

    args = sys.argv[1:]
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-') and not arg.startswith('--'):
            have_flag = True
            for ch in arg[1:]:
                if ch == 'l':
                    count_lines = True
                elif ch == 'w':
                    count_words = True
                elif ch == 'c':
                    count_chars = True
            i += 1
        else:
            filename = arg
            i += 1

    if not have_flag:
        count_lines = True
        count_words = True
        count_chars = True

    if filename is None or filename == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(filename, 'rb') as f:
            data = f.read()

    results = []
    if count_chars:
        results.append(str(len(data)))
    if count_lines:
        # A final line with no trailing newline still counts as a line
        lines = data.split(b'\n')
        line_count = len(lines) - 1
        if len(lines[-1]) > 0:
            line_count += 1
        results.append(str(line_count))
    if count_words:
        text = data.decode('latin-1')  # preserves all bytes
        words = text.split()
        results.append(str(len(words)))

    print(' '.join(results))


if __name__ == '__main__':
    main()

